import { SvgMpaIcon } from "../../assets/icons";

export type SupportedSize = "small" | "medium" | "large" | "x-large";

export const getIconSize = (size?: SupportedSize): string => {
  const map: Record<SupportedSize, string> = {
    small: "16",
    medium: "20",
    large: "24",
    "x-large": "32",
  };
  return map[size || "medium"];
};

export const debounce = (func: (...args: any) => any, wait: number) => {
  let timerId: any;
  return (...arg: any) => {
    if (timerId) {
      clearTimeout(timerId);
    }
    timerId = setTimeout(() => {
      func(...arg);
    }, wait);
  };
};

export const checkMpaIcon = (icon: string) => {
  return Object.keys(SvgMpaIcon).includes(icon);
};

export const getStatusColour = (status?: string) => {
  switch (status) {
    case "Pending":
      return "warning-soft";
    case "Rejected":
      return "error";
    case "Completed":
      return "success";
    default:
      return "surface";
  }
};

export const getIcon = (icon: string) => {
  switch (icon) {
    case "edit":
      return "Edit";
    case "editSolid":
      return "PenToSquareSolid_Fa";
    case "pencil":
      return "Pencil_SGDS";
    case "trash":
      return "Trash_SGDS";
    case "file":
      return "Download_SGDS";
    case "eye":
      return "OutlinePassword_Other";
    case "clear":
      return "Reload";
    case "pencilEdit":
      return "Pencil1";
    case "login":
      return "Login";
    case "update":
      return "PenToSquareSolid_Fa";
    case "downloadTxt":
      return "DownloadText_SGDS"
    case "downloadCsv":
      return "DownloadCsv_SGDS"
    case "downloadPdf":
      return "DownloadPdf_SGDS"
    case "downloadXls":
      return "DownloadXls_SGDS"
    default:
      return undefined;
  }
};

export const getDefaultTooltipText= (text: string) => {
    switch (text.toLowerCase()) {
    case "edit":
      return "Edit";
    case "delete":
      return "Delete";
    case "view":
      return "View";
    case "download":
      return "Download";
    default:
      return "";
  }
};

export const ignoreKey = (ev: KeyboardEvent) => {
  const exclude = ["e", "E"];
  if (exclude.includes(ev.key)) {
    ev.preventDefault();
  }
};
